-- One skill row THIS BOOK DEFINES, with the percentage it prints rather than
-- the emitter's base-0 stub. A Special O.C.C. Skill of the Old Believer, on
-- printed 128: Sculpt, Carve & Whittle Wood, 70% +3% per level. Filed Technical
-- beside the other craft skills this class takes.
--
-- The class's three OTHER special skills already have catalog rows and are
-- overridden per class instead, which is what `base` is for: Gemology 25 -> 50,
-- Rope Works 30 -> 60, and Masonry left alone because the book's 40% +5%
-- matches the row exactly.
--
-- WORTH KNOWING: Gemology appears in TWO classes in this book with DIFFERENT
-- progressions - 50% +3% here and 50% +5% for the Mystic Kuznya - which is why
-- neither is written onto the catalog row.
INSERT OR IGNORE INTO skills (name, category, base, per_level, source, source_book) VALUES ('Sculpt, Carve & Whittle Wood', 'Technical', 70, 3, 'import', 'Rifts World Book 18: Mystic Russia p.127-131');


